def load_rows(paths, limit, strict=False):
    rows, errors = [], []
    for p in paths:
        data = read(p, limit, strict)
        if len(data) == 0:
            errors.append(p)
            continue
        rows.extend(data)
    return rows, errors

public static int[] totals(int[] a, int[] b, int limit) {
    int[] out = new int[Math.min(a.length, b.length)];
    for (int i = 0; i < out.length; i++) {
        out[i] = a[i] + b[i];
        if (out[i] > limit) { out[i] = limit; }
    }
    return out;
}

